export type ManifestRow = {
    readonly id: OperationId;
    readonly family: Family;
    readonly risk: Risk;
    readonly gate: Gate;
    readonly send: boolean;
    readonly precondition: "provider" | "none";
    readonly docUrl: string;
    readonly pathResourceSegment: number | null;
    readonly preflight: readonly OperationId[];
    readonly argsSchema: z.ZodTypeAny;
    readonly bodySchema: z.ZodTypeAny | null;
    readonly projection: readonly string[];
} & ({
    readonly disposition: "ready";
    readonly method: HighLevelMethod;
    readonly path: string;
    readonly version: string;
    readonly scope: string;
} | {
    readonly disposition: "provider_absent";
    readonly method: HighLevelMethod | null;
    readonly path: string | null;
    readonly version: string | null;
    readonly scope: string | null;
});

export interface OperationRunContext {
    readonly locationId: string;
    readonly companyId?: string;
    readonly prepared?: PreparedUpload;
    readonly approvalContext?: RequestApprovalContext;
}

export interface ReadDraft {
    path: string;
    query?: Record<string, string>;
    body?: unknown;
}

export interface PreflightRequester {
    read(op: OperationId, draft: ReadDraft): Promise<unknown>;
}

export type DraftBody = {
    kind: "json";
    value: unknown;
} | {
    kind: "multipart";
    fields: Record<string, string>;
    file: {
        field: string;
        upload: PreparedUpload;
    };
};

export interface RequestApprovalContext {
    stateDigest?: string;
    values: Record<string, unknown>;
    identities: Record<string, readonly string[]>;
}

export interface RequestDraft {
    approvalContext?: RequestApprovalContext;
    path: string;
    query?: Record<string, string>;
    body?: DraftBody;
    resource: string;
}

export interface SpecBase<A = Record<string, unknown>> {
    readonly id: OperationId;
    readonly family: Family;
    readonly title: string;
    readonly row: ManifestRow;
    readonly endpoint: HighLevelEndpoint;
    readonly args: z.ZodType<A>;
    readonly nested: boolean;
    readonly preflight: readonly OperationId[];
    ownership?(pre: PreflightRequester, a: A, ctx: OperationRunContext): Promise<void>;
    recordRefs(a: A): string[];
    fields(a: A): string[];
    targets(a: A): number;
    project(value: unknown): unknown;
    project(value: unknown, frozen: FrozenRequest): unknown;
}

export interface ReadSpec<A = Record<string, unknown>> extends SpecBase<A> {
    readonly risk: "R";
    readonly maxReads: number;
    prepareRead(a: A, ctx: OperationRunContext): Promise<RequestDraft>;
    nextPage?(value: unknown, prev: RequestDraft): RequestDraft | null;
}

export type RecheckResult = {
    ok: true;
} | {
    ok: false;
    reason: "published" | "sent" | "not_draft" | "gone" | "changed";
};

export interface MutationSpec<A = Record<string, unknown>> extends SpecBase<A> {
    readonly risk: "C" | "D";
    readonly gate: Exclude<Gate, "R">;
    readonly send: boolean;
    readonly precondition: "provider" | "none";
    prepare(pre: PreflightRequester, a: A, ctx: OperationRunContext): Promise<RequestDraft>;
    recordId?(value: unknown): string | undefined;
    recordId?(value: unknown, frozen: FrozenRequest): string | undefined;
    recheck?(pre: PreflightRequester, frozen: FrozenRequest, ctx: OperationRunContext): Promise<RecheckResult>;
}

